"use client";

import React, { useState, useEffect, useCallback } from "react";
import { useAuth } from "@/context/AuthContext";
import { db, transactionalMutation, LocalCallLog, LocalUser, LocalLead } from "@/lib/db";
import { SearchableSelect, SearchableOption } from "@/components/SearchableSelect";
import { PhoneCall, CheckCircle2, AlertCircle, Download } from "lucide-react";
import excelUsers from "@/lib/excel_users.json";
import { exportCallLogs } from "@/lib/excelExport";
import { QueueList } from "@/components/QueueList";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { PageHeader } from "@/components/ui/PageHeader";
import { MetricCard } from "@/components/ui/MetricCard";

export default function CallLogsPage() {
  const { currentUser, isAdmin } = useAuth();

  const [loading, setLoading] = useState(true);
  const [logs, setLogs] = useState<LocalCallLog[]>([]);
  const [usersMap, setUsersMap] = useState<Map<string, LocalUser>>(new Map());
  const [leadsMap, setLeadsMap] = useState<Map<string, LocalLead>>(new Map());

  const [selectedLeadId, setSelectedLeadId] = useState("");
  const [outcome, setOutcome] = useState("");
  const [notes, setNotes] = useState("");
  const [nextFollowup, setNextFollowup] = useState("");

  const [submitting, setSubmitting] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState("");

  const commonOutcomes = [
    "No response (followup)",
    "Happy call",
    "Not interested",
    "Requested more info",
    "Wrong Number",
    "Other"
  ];

  const leadOptions: SearchableOption[] = React.useMemo(() => {
    const excelOptions: SearchableOption[] = (excelUsers as Array<{ name?: string; username: string }>).map((eu) => ({
      value: `EXCEL::${eu.username}::${eu.name || eu.username}`,
      label: `${eu.name || eu.username} (@${eu.username})`,
      searchText: eu.username + " " + (eu.name || "")
    }));
    return excelOptions.sort((a, b) => a.label.localeCompare(b.label));
  }, []);

  const loadData = useCallback(async () => {
    try {
      const fetchedLogs = await db.call_logs.toArray();
      fetchedLogs.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
      const allUsers = await db.users.toArray();
      const uMap = new Map<string, LocalUser>();
      allUsers.forEach(u => uMap.set(u.user_id, u));
      const allLeads = await db.leads.toArray();
      const lMap = new Map<string, LocalLead>();
      allLeads.forEach(l => lMap.set(l.lead_id, l));
      setUsersMap(uMap);
      setLeadsMap(lMap);
      setLogs(fetchedLogs);
    } catch (err) {
      console.error("Failed to load logs:", err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    let active = true;
    loadData().then(() => { if (!active) return; });
    return () => { active = false; };
  }, [loadData]);

  const handleLogCall = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) return;

    if (!selectedLeadId && !outcome) {
      setError("Please select a lead and provide an outcome.");
      return;
    }
    if (!selectedLeadId) {
      setError("Please select a lead.");
      return;
    }
    if (!outcome) {
      setError("Please select a call outcome/response.");
      return;
    }

    setSubmitting(true);
    setError("");
    setSuccess(false);

    try {
      const nextFollowupDate = (outcome === "No response (followup)" || outcome === "Requested more info") ? (nextFollowup || null) : null;

      const log: LocalCallLog = {
        log_id: crypto.randomUUID(),
        user_id: currentUser.user_id,
        lead_id: selectedLeadId,
        timestamp: new Date().toISOString(),
        outcome: outcome,
        notes: notes.trim() || null,
        next_followup_date: nextFollowupDate,
      };

      await transactionalMutation("call_logs", "INSERT", log);

      if (nextFollowupDate) {
        const leadNameMatch = selectedLeadId.split("::");
        const leadDisplay = leadNameMatch.length === 3 ? `${leadNameMatch[2]} (@${leadNameMatch[1]})` : selectedLeadId;

        const followupTask = {
          task_id: crypto.randomUUID(),
          assigned_to: currentUser.user_id,
          assigned_by: currentUser.user_id,
          title: "Follow-up Call",
          description: `Scheduled follow-up for: ${leadDisplay}\nNotes: ${notes.trim() || "No notes"}`,
          priority: "High" as const,
          status: "Pending" as const,
          source: "manual" as const,
          template_id: null,
          related_lead_id: selectedLeadId,
          due_date: nextFollowupDate,
          started_at: null,
          completed_at: null,
          proof_note: null,
          proof_photo_url: null,
          created_at: new Date().toISOString(),
        };
        await transactionalMutation("tasks", "INSERT", followupTask);
      }

      setSuccess(true);

      setSelectedLeadId("");
      setOutcome("");
      setNotes("");
      setNextFollowup("");

      await loadData();

      setTimeout(() => setSuccess(false), 3000);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      setError(msg || "Failed to log call.");
    } finally {
      setSubmitting(false);
    }
  };

  const showFollowup = outcome === "No response (followup)" || outcome === "Requested more info";

  // Format identity standard: "{Name} (@{Username}) - {Phone}"
  const getLeadDisplay = (lead_id: string) => {
    if (lead_id.startsWith("EXCEL::")) {
      const parts = lead_id.split("::");
      if (parts.length === 3) {
        return `${parts[2]} (@${parts[1]})`;
      }
    }
    const lead = leadsMap.get(lead_id);
    if (lead) {
      if (lead.business_name.includes("(@")) return lead.business_name;
      return `${lead.business_name} - ${lead.phone || "N/A"}`;
    }
    return lead_id;
  };

  const getAgentDisplay = (user_id?: string | null) => {
    if (!user_id) return "System/Unknown";
    const user = usersMap.get(user_id);
    if (!user) return "Unknown Agent";
    return `${user.name} (@${user.email})`;
  };

  const todayKey = new Date().toISOString().slice(0, 10);
  const callsToday = logs.filter((log) => log.timestamp.startsWith(todayKey)).length;
  const followupsScheduled = logs.filter((log) => Boolean(log.next_followup_date)).length;
  const reachedClients = logs.filter((log) => !log.outcome.toLowerCase().includes("no response")).length;

  return (
    <div className="app-page">
      <PageHeader
        eyebrow="Communication desk"
        icon={<PhoneCall size={18} />}
        title="Call activity"
        description="Capture outcomes, schedule follow-ups, and keep a trustworthy history of every client conversation."
        actions={currentUser ? (
          <Button size="sm" variant="outline" onClick={() => exportCallLogs(currentUser.user_id, isAdmin)} icon={<Download size={14} />}>
            Export history
          </Button>
        ) : undefined}
      />

      <div className="metric-grid">
        <MetricCard label="Calls today" value={callsToday} icon={<PhoneCall size={17} />} note="Recorded in the current calendar day" />
        <MetricCard label="Total records" value={logs.length} icon={<CheckCircle2 size={17} />} tone="neutral" note="All locally available call outcomes" />
        <MetricCard label="Follow-ups planned" value={followupsScheduled} icon={<AlertCircle size={17} />} tone="warning" note="Calls with a scheduled next step" />
        <MetricCard label="Clients reached" value={reachedClients} icon={<CheckCircle2 size={17} />} tone="success" note="Outcomes other than no response" />
      </div>

      <div className="workspace-split">
        <section className="surface-panel overflow-hidden" aria-labelledby="log-call-title">
          <div className="border-b border-[var(--border-subtle)] bg-[var(--surface-secondary)] p-5">
            <p className="section-kicker">New activity</p>
            <h2 id="log-call-title" className="mt-1 section-title">Record a call outcome</h2>
            <p className="mt-1 text-[12px] leading-5 text-[var(--text-muted)]">A follow-up task is created automatically when the selected outcome needs another contact.</p>
          </div>

          <form onSubmit={handleLogCall} className="space-y-5 p-5 sm:p-6">
            <div>
              <label className="field-label">Client or lead</label>
              <SearchableSelect options={leadOptions} value={selectedLeadId} onChange={setSelectedLeadId} placeholder="Search by name or username" required />
            </div>

            <div>
              <label htmlFor="call-outcome" className="field-label">Outcome</label>
              <select id="call-outcome" value={outcome} onChange={(event) => setOutcome(event.target.value)} className="field-control" required>
                <option value="" disabled>Select an outcome</option>
                {commonOutcomes.map((option) => <option key={option} value={option}>{option}</option>)}
              </select>
            </div>

            <div>
              <label htmlFor="call-notes" className="field-label">Conversation notes <span className="font-normal text-[var(--text-muted)]">(optional)</span></label>
              <textarea id="call-notes" value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Important details, objections, or commitments" rows={4} className="field-control resize-y" />
            </div>

            {showFollowup && (
              <Input label="Next follow-up date" type="date" value={nextFollowup} onChange={(event) => setNextFollowup(event.target.value)} description="A high-priority task will be added to My Day." />
            )}

            {error && <div className="alert-panel alert-panel--danger" role="alert"><AlertCircle size={16} className="mt-0.5 shrink-0" /><span>{error}</span></div>}
            {success && <div className="alert-panel alert-panel--success" role="status"><CheckCircle2 size={16} className="mt-0.5 shrink-0" /><span>Call recorded and the activity history is up to date.</span></div>}

            <div className="flex justify-end border-t border-[var(--border-subtle)] pt-5">
              <Button type="submit" isLoading={submitting} icon={<PhoneCall size={15} />} disabled={!selectedLeadId || !outcome}>Record call</Button>
            </div>
          </form>
        </section>

        <QueueList
          title="Recent call history"
          items={logs.map((log) => ({
            id: log.log_id,
            primaryNode: (
              <div>
                <p className="text-[13px] font-semibold leading-snug text-[var(--text-primary)]">{getLeadDisplay(log.lead_id)}</p>
                <p className="mt-1 text-[10px] font-semibold uppercase tracking-[0.06em] text-[var(--text-muted)]">Agent · <span className="normal-case tracking-normal text-[var(--text-secondary)]">{getAgentDisplay(log.user_id)}</span></p>
                {log.notes && <p className="mt-2 rounded-[var(--radius-sm)] border border-[var(--border-subtle)] bg-[var(--surface-primary)] p-2.5 text-[12px] leading-5 text-[var(--text-secondary)]">{log.notes}</p>}
              </div>
            ),
            statusText: log.outcome,
            statusVariant: "brand",
            timestamp: new Date(log.timestamp).toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }),
          }))}
          emptyMessage={loading ? "Loading call activity…" : "No calls have been recorded yet."}
          onRefresh={loadData}
        />
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useAuth } from "@/context/AuthContext";
import { supabase, isSupabaseConfigured } from "@/lib/supabaseClient";
import { CONVERTED_STAGES } from "@/lib/pipelineRules";
import { db } from "@/lib/db";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  CartesianGrid,
  Cell,
} from "recharts";
import {
  TrendingUp,
  Users,
  AlertTriangle,
  CheckCircle2,
  Calendar,
  BarChart3,
  Layers
} from "lucide-react";
import FunnelTab from "./FunnelTab";
import { Chip } from "@/components/ui/Chip";
import { PageHeader } from "@/components/ui/PageHeader";
import { MetricCard } from "@/components/ui/MetricCard";
import { Input } from "@/components/ui/Input";
import { EmptyState } from "@/components/ui/EmptyState";

interface KpiRow {
  user_id: string;
  name: string;
  completion_rate: number;
  tasks_assigned: number;
  tasks_completed: number;
  attendance_status: string;
  leads_converted: number;
  tickets_resolved: number;
  calls_made: number;
}

async function buildLocalKpiRows(date: string): Promise<KpiRow[]> {
  const users = await db.users.toArray();
  const tasks = await db.tasks.where("due_date").equals(date).toArray();
  const attendance = await db.attendance.toArray();
  const leads = await db.leads.toArray();
  const calls = await db.call_logs.toArray();

  return users.map((u) => {
    const userTasks = tasks.filter((t) => t.assigned_to === u.user_id);
    const completed = userTasks.filter((t) => t.status === "Completed").length;
    const assigned = userTasks.length;
    const att = attendance.find((a) => a.user_id === u.user_id && a.date === date);
    const converted = leads.filter(
      (l) =>
        l.assigned_to === u.user_id &&
        CONVERTED_STAGES.includes(l.status as typeof CONVERTED_STAGES[number])
    ).length;
    const callsMade = calls.filter((c) => c.user_id === u.user_id && c.timestamp.startsWith(date)).length;

    return {
      user_id: u.user_id,
      name: u.name,
      completion_rate: assigned === 0 ? 0 : Math.round((completed / assigned) * 100),
      tasks_assigned: assigned,
      tasks_completed: completed,
      attendance_status: att ? (att.clock_in ? "Present" : "Absent") : "Absent",
      leads_converted: converted,
      tickets_resolved: 0,
      calls_made: callsMade,
    };
  });
}

function AttBadge({ status }: { status: string }) {
  const variant = status === "Present" ? "success" : status === "Late" ? "warning" : "danger";
  return <Chip variant={variant} size="sm">{status}</Chip>;
}

export default function ManagerKpiPage() {
  const { currentUser, isAdmin } = useAuth();
  const [rows, setRows] = useState<KpiRow[]>([]);
  const [date] = useState(new Date().toISOString().slice(0, 10));
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<"Team" | "Funnel">("Team");

  useEffect(() => {
    let active = true;
    if (!currentUser) return;

    (async () => {
      if (isSupabaseConfigured) {
        const { data } = await supabase
          .from("kpi_daily_snapshot")
          .select(
            "user_id, completion_rate, tasks_assigned, tasks_completed, attendance_status, leads_converted, tickets_resolved, users!inner(name)"
          )
          .eq("date", date);

        const mapped: KpiRow[] = ((data || []) as unknown as Array<{ user_id: string; users: { name: string }; completion_rate: number; tasks_assigned: number; tasks_completed: number; attendance_status: string; leads_converted: number; tickets_resolved: number; calls_made?: number }>).map((r) => ({
          user_id: r.user_id,
          name: r.users?.name || "Unknown",
          completion_rate: Number(r.completion_rate) || 0,
          tasks_assigned: r.tasks_assigned || 0,
          tasks_completed: r.tasks_completed || 0,
          attendance_status: r.attendance_status ?? "Absent",
          leads_converted: r.leads_converted || 0,
          tickets_resolved: r.tickets_resolved || 0,
          calls_made: r.calls_made || 0,
        }));
        let finalMapped = mapped;
        if (!isAdmin && currentUser) {
          const directSubordinates = await db.users.where("manager_id").equals(currentUser.user_id).toArray();
          const subIds = new Set(directSubordinates.map(u => u.user_id));
          subIds.add(currentUser.user_id);
          finalMapped = mapped.filter(r => subIds.has(r.user_id));
        }
        finalMapped.sort((a, b) => b.completion_rate - a.completion_rate);
        if (active) {
          setRows(finalMapped);
          setLoading(false);
        }
      } else {
        let computed = await computeLocalKpis(date);
        if (!isAdmin && currentUser) {
          const directSubordinates = await db.users.where("manager_id").equals(currentUser.user_id).toArray();
          const subIds = new Set(directSubordinates.map(u => u.user_id));
          subIds.add(currentUser.user_id);
          computed = computed.filter(r => subIds.has(r.user_id));
        }
        computed.sort((a, b) => b.completion_rate - a.completion_rate);
        if (active) {
          setRows(computed);
          setLoading(false);
        }
      }
    })();
    return () => { active = false; };
  }, [currentUser, date, isAdmin]);

  const showOnboardingCols = isAdmin || hasOnboarding;
  const showSupportCols = isAdmin || hasSupport;

  const flagged = rows.filter(
    (r) => r.completion_rate < 50 || r.attendance_status !== "Present"
  );
  const avgCompletion =
    rows.length === 0
      ? 0
      : Math.round(rows.reduce((s, r) => s + (r.completion_rate || 0), 0) / rows.length) || 0;

  const presentCount = rows.filter((row) => row.attendance_status === "Present").length;

  return (
    <div className="app-page">
      <PageHeader
        eyebrow="Performance intelligence"
        icon={<BarChart3 size={18} />}
        title={isAdmin ? "Team performance" : "My performance"}
        description="Compare execution, attendance, conversion, and pipeline health without losing the underlying operational detail."
        actions={
          <Input type="date" value={date} onChange={(event) => setDate(event.target.value)} leftIcon={<Calendar size={15} />} containerClassName="w-full sm:w-[190px]" aria-label="KPI date" />
        }
      />

      <div className="segmented-control w-fit" aria-label="Performance report view">
        <button type="button" aria-pressed={activeTab === "Team"} onClick={() => setActiveTab("Team")}><span className="flex items-center gap-2"><Users size={14} /> Team execution</span></button>
        <button type="button" aria-pressed={activeTab === "Funnel"} onClick={() => setActiveTab("Funnel")}><span className="flex items-center gap-2"><Layers size={14} /> Pipeline funnel</span></button>
      </div>

      {activeTab === "Team" ? (
        <>
          <div className="metric-grid">
            <MetricCard label="Active staff" value={rows.length} icon={<Users size={17} />} tone="neutral" note="People included in the selected snapshot" />
            <MetricCard label="Average completion" value={`${avgCompletion}%`} icon={<TrendingUp size={17} />} tone="brand" note="Mean task completion across visible staff" />
            <MetricCard label="Needs attention" value={flagged.length} icon={<AlertTriangle size={17} />} tone="warning" note="Low completion or missing attendance" />
            <MetricCard label="Present" value={presentCount} icon={<CheckCircle2 size={17} />} tone="success" note={`Attendance recorded for ${date}`} />
          </div>

          {loading ? (
            <section className="surface-panel grid min-h-[360px] place-items-center"><p className="text-[13px] font-medium text-[var(--text-muted)]">Loading KPI snapshot…</p></section>
          ) : rows.length > 0 ? (
            <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_360px]">
              <section className="surface-panel overflow-hidden" aria-labelledby="completion-chart-title">
                <div className="border-b border-[var(--border-subtle)] p-5"><p className="section-kicker">Execution distribution</p><h2 id="completion-chart-title" className="mt-1 section-title">Task completion rate</h2></div>
                <div className="h-[320px] p-4 sm:p-5">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={rows} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                      <CartesianGrid strokeDasharray="3 3" stroke="var(--border-subtle)" vertical={false} />
                      <XAxis dataKey="name" stroke="var(--text-muted)" fontSize={11} tickLine={false} axisLine={false} />
                      <YAxis stroke="var(--text-muted)" fontSize={11} domain={[0, 100]} tickLine={false} axisLine={false} />
                      <Tooltip cursor={{ fill: "var(--surface-hover)" }} contentStyle={{ backgroundColor: "var(--surface-elevated)", borderColor: "var(--border-default)", borderRadius: "10px", color: "var(--text-primary)", fontSize: "12px", boxShadow: "var(--shadow-popover)" }} />
                      <Bar dataKey="completion_rate" radius={[5, 5, 0, 0]} maxBarSize={48}>
                        {rows.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.completion_rate >= 80 ? "var(--status-success)" : entry.completion_rate >= 50 ? "var(--brand-500)" : "var(--status-danger)"} />)}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </section>

              <aside className="surface-panel overflow-hidden" aria-labelledby="attention-list-title">
                <div className="border-b border-[var(--border-subtle)] bg-[var(--surface-secondary)] p-5"><p className="section-kicker">Management focus</p><h2 id="attention-list-title" className="mt-1 section-title">People needing attention</h2></div>
                <div className="max-h-[320px] space-y-2 overflow-y-auto p-4">
                  {flagged.length ? flagged.map((row) => (
                    <div key={row.user_id} className="rounded-[var(--radius-md)] border border-[var(--border-subtle)] p-3">
                      <div className="flex items-center justify-between gap-3"><p className="truncate text-[12px] font-semibold text-[var(--text-primary)]">{row.name}</p><span className="text-[12px] font-semibold tabular-nums text-[var(--status-warning)]">{row.completion_rate}%</span></div>
                      <div className="mt-2 flex flex-wrap gap-2"><AttBadge status={row.attendance_status} /><Chip variant={row.completion_rate < 50 ? "danger" : "neutral"} size="sm">{row.tasks_completed}/{row.tasks_assigned} tasks</Chip></div>
                    </div>
                  )) : <EmptyState compact icon={<CheckCircle2 size={20} />} title="No performance flags" description="Visible staff meet the current attendance and completion thresholds." />}
                </div>
              </aside>
            </div>
          ) : null}

          <section className="data-table-shell" aria-labelledby="kpi-table-title">
            <div className="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--border-subtle)] px-5 py-4"><div><p className="section-kicker">Detailed scorecard</p><h2 id="kpi-table-title" className="mt-1 section-title">Team KPI register</h2></div><Chip variant="neutral" size="sm">{date}</Chip></div>
            {rows.length === 0 && !loading ? (
              <div className="p-5"><EmptyState icon={<BarChart3 size={21} />} title="No KPI snapshot" description={`No performance data is available for ${date}.`} /></div>
            ) : (
              <div className="overflow-x-auto">
                <table className="min-w-[760px]">
                  <thead><tr><th>Team member</th><th>Attendance</th><th>Completion</th><th>Assigned / done</th>{showOnboardingCols && <th>Converted</th>}{showSupportCols && <th>Calls</th>}</tr></thead>
                  <tbody>
                    {rows.map((row) => (
                      <tr key={row.user_id}>
                        <td><p className="font-semibold text-[var(--text-primary)]">{row.name}</p></td>
                        <td><AttBadge status={row.attendance_status} /></td>
                        <td><div className="flex min-w-[140px] items-center gap-3"><div className="h-2 flex-1 overflow-hidden rounded-full bg-[var(--surface-tertiary)]"><div className={`h-full rounded-full ${row.completion_rate >= 80 ? "bg-[var(--status-success)]" : row.completion_rate >= 50 ? "bg-[var(--brand-500)]" : "bg-[var(--status-danger)]"}`} style={{ width: `${Math.min(row.completion_rate, 100)}%` }} /></div><span className="w-10 text-right font-semibold tabular-nums text-[var(--text-primary)]">{row.completion_rate}%</span></div></td>
                        <td className="font-mono text-[12px]">{row.tasks_completed} / {row.tasks_assigned}</td>
                        {showOnboardingCols && <td className="font-semibold tabular-nums text-[var(--text-primary)]">{row.leads_converted}</td>}
                        {showSupportCols && <td className="font-semibold tabular-nums text-[var(--text-primary)]">{row.calls_made}</td>}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </section>
        </>
      ) : <FunnelTab />}
    </div>
  );
}

